#include "resident/domains/growth/growth_model.hpp"
// 真实服务半日与永久源原子成组；不重新付款、不接管军籍、不按等待墙钟补进度。
#include "growth_recovery_rules.hpp"
#include "growth_condition_services.hpp"
#include <algorithm>
#include <limits>
namespace hanmo::resident {namespace {
template<class T> Outcome<T> fail(const StableId& code,const StableId& id){return {false,{},common_failure(code,id).error};}
Status phase_valid(const CommonStore& c,const DynamicStepInput& phase){return c.tick()>=0&&c.tick()<std::numeric_limits<Integer>::max()&&phase.from_tick==c.tick()&&phase.to_tick==c.tick()+1?common_success():common_failure("GrowthRecoveryPhaseInvalid");}
// 只核热当前真实参与者和同处；旧期资格仍由完整历史读按原事实边界重核。
Status present(const CommonStore& c,const CommonCatalog& catalog,const GrowthRecoveryService& s,const StableId& action){const auto* patient=c.actor(s.actor_id);const auto* provider=c.actor(s.provider_actor_id);const auto* role=catalog.roles.find(s.role_id);if(!patient||!provider||!patient->alive||!provider->alive||!patient->available||!provider->available||patient->action_id!=action||provider->action_id!=action||!role||role->place_id!=s.place_id)return common_failure("GrowthRecoveryServiceUnavailable",action);auto p=c.resolved_location(s.actor_id),q=c.resolved_location(s.provider_actor_id);const auto* a=p.ok?std::get_if<SettlementLocation>(&p.value):nullptr;const auto* b=q.ok?std::get_if<SettlementLocation>(&q.value):nullptr;return a&&b&&a->place_id==s.place_id&&b->place_id==s.place_id?common_success():common_failure("GrowthRecoveryServiceNotPresent",action);}
}
Status bind_growth_recovery_service_in_candidate(CommonStore& c,const GrowthState& growth,const CommonCatalog& shared,const GrowthRecoveryCatalog& catalog,GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& access,const ActionCoreView& action){
    const auto* original=growth.life_activities.find(action.id);if(!original||original->view.kind!=LifeActivityKind::service||original->view.activity!="rest")return common_success();const auto* method=catalog.service_roles.find(original->context.role_id);if(!method)return common_success();if(state.services.find(action.id))return common_failure("GrowthRecoveryServiceAlreadyBound",action.id);const auto* terms=std::get_if<ServiceTerms>(&original->terms);const auto* current=c.action(action.id);if(!terms||!current||action.kind!="service"||action.start_tick!=c.tick()||current->start_tick!=action.start_tick||current->actor_id!=action.actor_id||current->remaining_ticks!=terms->duration||original->view.phase!=LifeActivityPhase::active||original->view.actor_id!=action.actor_id||original->view.start_tick!=action.start_tick)return common_failure("GrowthRecoveryOriginalServiceRequired",action.id);
    GrowthRecoveryService service{action.actor_id,original->view.provider_actor_id,original->context.role_id,original->context.place_id,*method,action.start_tick,terms->duration,{}};auto valid=present(c,shared,service,action.id);if(!valid.ok)return valid;
    if(!access.service_qualified_now)return common_failure("GrowthRecoveryQualificationRequired",action.id);valid=access.service_qualified_now(service);if(!valid.ok)return valid;
    if(!state.services.insert(action.id,service))return common_failure("GrowthRecoveryServiceAlreadyBound",action.id);auto checked=read_growth_recovery_progress_in_candidate(c,growth,catalog,state,access,action.actor_id);return checked.ok?common_success():Status{false,{},checked.error};
}
Outcome<StableId> step_growth_recovery_service_in_candidate(CommonStore& c,const GrowthState& growth,const CommonCatalog& shared,const GrowthRecoveryCatalog& catalog,GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& access,const ActionCoreView& action,const DynamicStepInput& phase){
    auto valid=phase_valid(c,phase);if(!valid.ok)return {false,{},valid.error};const auto* original=growth.life_activities.find(action.id);const auto* service=state.services.find(action.id);if(!service){if(original&&original->view.kind==LifeActivityKind::service&&original->view.activity=="rest"&&catalog.service_roles.find(original->context.role_id))return fail<StableId>("GrowthRecoveryServiceBindingMissing",action.id);return {true,{}, {}};}
    const auto* current=c.action(action.id);if(!current||action.kind!="service"||current->actor_id!=service->actor_id||action.actor_id!=service->actor_id||current->remaining_ticks!=action.remaining_ticks||action.remaining_ticks<1||action.remaining_ticks>service->duration||action.start_tick!=service->start_tick||std::find(phase.existing_action_ids.begin(),phase.existing_action_ids.end(),action.id)==phase.existing_action_ids.end())return fail<StableId>("GrowthRecoveryStepSourceMismatch",action.id);for(const auto& row:state.closures.rows())if(row.second.action_id==action.id)return fail<StableId>("GrowthRecoveryServiceClosed",action.id);
    const auto ordinal=service->duration-action.remaining_ticks+1;if(phase.to_tick<service->start_tick||phase.to_tick-service->start_tick!=ordinal)return fail<StableId>("GrowthRecoveryStepClockMismatch",action.id);valid=present(c,shared,*service,action.id);if(!valid.ok)return {false,{},valid.error};
    auto prior=read_growth_recovery_progress_in_candidate(c,growth,catalog,state,access,action.actor_id,&phase);if(!prior.ok)return {false,{},prior.error};const auto points=growth_recovery_service_points(service->method);auto math=apply_growth_recovery_points(prior.value,points);if(!math.ok)return {false,{},math.error};
    GrowthRecoveryStep record;record.action_id=action.id;record.tick=phase.to_tick;record.ordinal=ordinal;record.before=prior.value;record.after=math.value.after;record.offered_points=points;record.used_points=math.value.used_points;auto id=c.next_id("recovery");if(!id.ok)return {false,{},id.error};valid=c.append_fact({id.value,"personal_recovery_credit","personal_injury_recovery"});if(!valid.ok)return {false,{},valid.error};if(!state.credits.insert(id.value,record))return fail<StableId>("GrowthRecoveryCreditCollision",id.value);
    if(!access.service_qualified_before)return fail<StableId>("GrowthRecoveryQualificationRequired",id.value);valid=access.service_qualified_before(*service,phase.to_tick,id.value);if(!valid.ok)return {false,{},valid.error};std::optional<GrowthConditionWriteBoundary> condition_boundary;if(access.condition_writer){auto opened=begin_growth_condition_write_in_candidate(c,{GrowthPersonalConditionBusiness::recovery_credit,action.id,phase.to_tick,ordinal},phase);if(!opened.ok)return {false,{},opened.error};condition_boundary=std::move(opened.value);}const auto* person=c.actor(action.actor_id);ActorMutation change;change.actor_id=action.actor_id;change.injury=record.after.injury;change.hp=std::min<Integer>(person->hp,growth_injury_hp_limit(record.after.injury));valid=c.apply_actor(change);if(!valid.ok)return {false,{},valid.error};if(condition_boundary){auto bound=bind_growth_recovery_condition_in_candidate(c,growth,catalog,state,id.value,*condition_boundary);if(!bound.ok)return {false,{},bound.error};valid=access.condition_writer->accept_bound_condition(std::move(bound.value));if(!valid.ok)return {false,{},valid.error};}return id;
}
Outcome<StableId> close_growth_recovery_service_in_candidate(CommonStore& c,const GrowthState& growth,const GrowthRecoveryCatalog& catalog,GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& access,const StableId& action,const StableId& reason,const StableId& cause,const DynamicStepInput* phase){
    const auto* service=state.services.find(action);if(!service)return {true,{}, {}};if(phase){auto valid=phase_valid(c,*phase);if(!valid.ok)return {false,{},valid.error};}for(const auto& row:state.closures.rows())if(row.second.action_id==action)return fail<StableId>("GrowthRecoveryServiceAlreadyClosed",action);const auto* original=growth.life_activities.find(action);if(!original||original->view.phase==LifeActivityPhase::active)return fail<StableId>("GrowthRecoveryOriginalTerminationRequired",action);const auto tick=phase?phase->to_tick:c.tick();if(original->view.completed_tick!=tick)return fail<StableId>("GrowthRecoveryClosureClockMismatch",action);
    GrowthRecoveryClosure closure;closure.action_id=action;closure.tick=tick;closure.reason=reason;closure.cause_fact_id=cause;for(const auto& row:state.credits.rows())if(row.second.action_id==action)++closure.provided_half_days;auto id=c.next_id("recovery");if(!id.ok)return {false,{},id.error};auto valid=c.append_fact({id.value,"personal_recovery_closed","personal_injury_recovery"});if(!valid.ok)return {false,{},valid.error};if(!state.closures.insert(id.value,closure))return fail<StableId>("GrowthRecoveryClosureCollision",id.value);
    // 只核本人同候选链；其他当轮行动尚未完成不触发全世界的中间态误拒。
    auto checked=read_growth_recovery_progress_in_candidate(c,growth,catalog,state,access,service->actor_id,phase);if(!checked.ok)return {false,{},checked.error};return id;
}
}
